"""Generate typed synchronous delegates from async signatures."""

import argparse
import ast
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def generate() -> str:
    lines = [
        "# Generated by scripts/gen_sync.py; do not edit.",
        "from __future__ import annotations",
        "from typing import Literal",
        "from decimal import Decimal",
        "from pathlib import Path",
        "import builtins",
        "from collections.abc import Iterator",
        "from ._blocking import Runner",
        "from ._stream import StreamCheckpoint",
        "from ._protocol import CompletionMilestone",
        "from ._generated.models import RunResult",
        "from .account import AsyncAccount, AsyncApiKeys",
        "from .billing import AsyncBilling",
        "from .swarms import AsyncSwarms",
        "",
    ]
    model_imports = set()
    for module in ["swarms", "account", "billing"]:
        tree = ast.parse((ROOT / "synth_ai" / f"{module}.py").read_text())
        for node in tree.body:
            if isinstance(node, ast.ImportFrom) and node.module == "_generated.models":
                model_imports.update(alias.name for alias in node.names)
        for cls in tree.body:
            if not isinstance(cls, ast.ClassDef) or not cls.name.startswith("Async"):
                continue
            name = cls.name.removeprefix("Async") + "Client"
            lines += [
                f"class {name}:",
                f"    def __init__(self, runner: Runner, source: {cls.name}) -> None:",
                "        self._runner=runner",
                "        self._async=source",
            ]
            if name == "AccountClient":
                lines += ["        self.api_keys=ApiKeysClient(runner, source.api_keys)"]
            for fn in cls.body:
                if not isinstance(fn, ast.AsyncFunctionDef) or fn.name.startswith("_"):
                    continue
                args = ast.unparse(fn.args)
                if fn.returns is None:
                    raise ValueError(f"{cls.name}.{fn.name} lacks a return annotation")
                returns = (
                    ast.unparse(fn.returns)
                    .replace("AsyncIterator", "Iterator")
                    .replace("AsyncGenerator", "Iterator")
                    .replace(", None]", "]")
                )
                positional = [a.arg for a in fn.args.args if a.arg != "self"]
                callargs = positional + [a.arg + "=" + a.arg for a in fn.args.kwonlyargs]
                if fn.args.vararg:
                    callargs += ["*" + fn.args.vararg.arg]
                if fn.args.kwarg:
                    callargs += ["**" + fn.args.kwarg.arg]
                call = f"self._async.{fn.name}(" + ",".join(callargs) + ")"
                runner = "iterate" if returns.startswith("Iterator[") else "call"
                lines += [
                    f"    def {fn.name}({args}) -> {returns}:",
                    f"        return self._runner.{runner}({call})",
                ]
            lines += [""]
    lines.insert(1, "from ._generated.models import (" + ", ".join(sorted(model_imports)) + ")")
    source = "\n".join(lines) + "\n"
    source = subprocess.run(
        ["ruff", "check", "--select", "I,F401", "--fix", "--stdin-filename", "_sync.py", "-"],
        input=source,
        text=True,
        capture_output=True,
        check=True,
    ).stdout
    return subprocess.run(
        ["ruff", "format", "--stdin-filename", "_sync.py", "-"],
        input=source,
        text=True,
        capture_output=True,
        check=True,
    ).stdout


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    source = generate()
    path = ROOT / "synth_ai/_sync.py"
    if args.check:
        if path.read_text() != source:
            raise SystemExit("sync delegates drift")
    else:
        path.write_text(source)
